create or replace function public.save_claimed_treasure_box_story_chapter_details(p_story_id uuid,p_chapter_id uuid,p_chapter_number integer,p_title text,p_body text,p_image_prompt text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if not exists(select 1 from public.treasure_box_stories s where s.id=p_story_id and s.creator_id=auth.uid()) then raise exception 'Story not found'; end if; if p_chapter_number<1 then raise exception 'Chapter number must be at least 1'; end if; if p_chapter_id is null then insert into public.treasure_box_story_chapters(story_id,chapter_number,title,body,image_prompt) values(p_story_id,p_chapter_number,nullif(trim(coalesce(p_title,'')),''),coalesce(p_body,''),nullif(trim(coalesce(p_image_prompt,'')),'')) returning id into v_id; else update public.treasure_box_story_chapters c set chapter_number=p_chapter_number,title=nullif(trim(coalesce(p_title,'')),''),body=coalesce(p_body,''),image_prompt=nullif(trim(coalesce(p_image_prompt,'')),''),updated_at=now() where c.id=p_chapter_id and c.story_id=p_story_id returning c.id into v_id; if v_id is null then raise exception 'Chapter not found'; end if; end if; return v_id; end; $$; revoke all on function public.save_claimed_treasure_box_story_chapter_details(uuid,uuid,integer,text,text,text) from public; grant execute on function public.save_claimed_treasure_box_story_chapter_details(uuid,uuid,integer,text,text,text) to authenticated;